  VALUES 
    (162::BIGINT, 'Es un excelente profesor, su pasión e intención de ayudar a todos de atreverse a intentarlo, de corregir para mejorar y no criticar y tratar de tener clases diferentes comparadas a otras es lo que lo diferencia de los demás. Y otra cosa que puedes estar seguro es de lo mucho que logras aprender.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, '8afc00a80192d06fd99be96478e4569a5dcf091105f1b69b9319c24c285f1579'::TEXT, ARRAY[545]::BIGINT[]),
