    (162::BIGINT, 'Calidad de profe lleve ingles básico y 2 con el no me arrepiento tiene que hablar en clase pero el profe es muy tuanis y muy comprensivo si tienes algún problema, además se pasa fácil y se aprende con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'c9a5435b566cee8d5d4cfcb0a39a54ec08bf92f74a487b9d5e598c766fcb7891'::TEXT, ARRAY[539]::BIGINT[]),
