    (162::BIGINT, 'la clase se vuelve amena y ayuda a los estudiantes a pasar haciendo trabajos en las clases virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-11-18T00:00:00+00:00'::TIMESTAMPTZ, '571d26e727fef83209cb8c14084260a99d9ba3a5ed0a382ba3151aa65dcfc726'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Profe todo GOD'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, '1440bad95631daba62ba62da0e2fa0ddfb51adaa9b6f23b3867ae8ff52fc002c'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Buen profesor. Deja muchas tareas pero son fáciles, todas son en grupo. Usted siempre va a hablar. Califica bien y el ambiente en clase es ameno. Matricule con él de fijo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e438c7315a0f0d548c2b2770a2c76e04dfbb7cea4541675e4fe802385e5db854'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Las clases son normales, nada fuera del otro mundo. Hace trabajos en clases grupales, nunca individual pero faciles. Tareas rapido y siempre intentara hacer que uno hable'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2025-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'cfa67ee725adb9e3cbf38f05f275170ea709ab32e2214e0557c6ae7f2f4efa82'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Es un profe muy chill, califica bastante tranquilo y el curso es extremadamente fácil, si tiene la oportunidad de matricular con él, hágalo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dc22547560159cad610917a58cc7e0ededc33e994e4fbb01a7bbe64f7a43fe0a'::TEXT, ARRAY[539]::BIGINT[]),
    (162::BIGINT, 'Es muy buen profe, muy carismático y ayuda hasta donde el puede'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fdcbc9ad6eb792cff8c5626c101b3dd9918ee19b98c270027649d25366f09dec'::TEXT, ARRAY[539]::BIGINT[]),
    (162::BIGINT, 'Es buen profe pero a veces cuesta entenderle. Hace muchas actividades lo que facilita un poco aprender los temas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2024-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'b36ccd39c52417b44c71a7bae842a82eb2e1066c323b11af84e18e776155b514'::TEXT, ARRAY[625, 545, 2379, 547]::BIGINT[]),
    (162::BIGINT, 'El profe es muy tuanis, pero eso es un problema porque los estudiantes no lo respetan. El profe es muy suave calificando. Y sinceramente no aprendí mucho con él'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'a30865369dc7c0c179cb32b11444119907ea168fa55800a2d9f85c1adbc6647c'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-05-14T00:00:00+00:00'::TIMESTAMPTZ, '8bc9136df7696aedc2a7200c21ca40e1474c782a906368f8f3e285d744346f4c'::TEXT, ARRAY[625, 545, 2379, 547]::BIGINT[]),
    (162::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-05-02T00:00:00+00:00'::TIMESTAMPTZ, '25bac02e1b45cd025615b44e1d740c92e11f26299d9f2cfb4fe37193bf2f5fb7'::TEXT, ARRAY[539]::BIGINT[]),
    (162::BIGINT, 'El profe hace que el curso no se sienta pesado, es muy comprensivo y ayuda bastante, se aprende bastante y él ayuda un montón. Lo recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'b73ad9b3ae20556831d94b174e4f06c9a8f1d1079ed6d4ece5a871dc7e4b1d40'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Un profe que califica suave, no le complica la vida al estudiante y además aprovecha para la parte virtual para evaluaciones, pero la verdad, es muy excelente profe si le pone interés aprendes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '0e86027cfac8d5c96044d519694f9360c40cf2cd36e67e4ec3e577fde44fab2b'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'Lo más difícil es el proyecto final (grupal), pero en general el curso con él se pasa fácil, es atento con los estudiantes, siempre llegaba como 30 min tarde, pero para ser clase de inglés no importa mucho. Se preocupa por el estudiante y los exámenes son fáciles y usan laptop o el cel.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a7d6fdbe75b36a1e63c96b529efe191c6fcfeb75476afcde8e4da7836b3b9a7e'::TEXT, ARRAY[547]::BIGINT[]),
    (162::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0535b6104a93b042f711458be8538af157a916b9ac55be33eecb52b252c6f3a9'::TEXT, ARRAY[625, 545, 2379, 547]::BIGINT[]),
    (162::BIGINT, 'El profe es una excelente persona y sabe enseñar muy bien! Califica muy suave y es muy comprensivo con las entregas. Siempre está atento a las dudas y le gusta escuchar a las personas. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2022-12-29T00:00:00+00:00'::TIMESTAMPTZ, 'b728a60fb1739a86896889effdb2a83616f0f76d45e6304d1c318ac3fa80ca4c'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'El mejor profe para llevar inglés, califica super bien, explica muy claro y es muy buena gente, matricule con el si puede hacerlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd3e0cec38d3d1363190a3cf798cc6136b5773fd3c89e518e002e87146afc3de4'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'El mejor profe de inglés que he tenido. Ayuda bastante, las clases no son aburridas, no califica rudo y entiende al estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'fc308556751ea2e6bfd372adf68ac9c0d8b8cbbfc8abe5a5d17b60eb07dbfe57'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'Este profe es una cosa maravillosa, califica suave la clase es interactiva, las tareas son fáciles y los exámenes también, si tienen la oportunidad de que el sea su profe dele de una sin miedo al éxito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-04T00:00:00+00:00'::TIMESTAMPTZ, '361d088a00cc62ab801fbb79a4aab6f3e3d78c94dc582eb9d6add533e5bd2454'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'El profe es tuanis y su clase son entretenidas, interactivas entre los estudiantes pero faciles y divertidas, califica bien y ayuda, de recomendacion, no falte ya que si hace evaluaciones de trabajo en clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '527e562d6b01c6fd0443af16f585bca90f3808364105a8c69af18d47b9e2cf7f'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'El mae es buena gente, y también es increíblemente desorganizado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '81c607270241c59228f2c5abcedae9d2a9f03bb6c654842ca01d3f7772543834'::TEXT, ARRAY[625]::BIGINT[]),
    (162::BIGINT, 'Es un excelente profesor, si quieres pasar fácil y con buena nota meta con el, 100% recomendado. Califica muy suave y ayuda cuando alguien presenta un problema con alguna evaluación.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'd5af069e8a6575ea97487cb2d56bf1243807f934565ea81eee5518b7059720a0'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'Explica super bien, deja trabajos todas las semanas fáciles de realizar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'bb561e066f297276fadfde950e49999b93498caeed741056a725b954ef0cb37e'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'Explica muy bien, las clases no son largas y siempre esta dispuesto a brindar material extra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'c88c0332a98cc37e4c0cc2c791d828ff4f7de8da426b0e91dc83bab3c74bac3f'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'No califica duro, da los temas que tiene que dar, da medio curso asincrónico y cuando da clases le interesa mucho la participación de los estudiantes. Lo recomiendo, pero si quiere aprender inglés busque mejor CONARE o autodidacta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '12c7ced2d059d8571f5c63f8f86b149d80b18b5fa162557b99d810481c2b0089'::TEXT, ARRAY[539]::BIGINT[]),
    (162::BIGINT, 'Explica de manera clara, las actividades son organizadas, siempre anuente a ayudar, no califica duro pero le interesa mucho la participación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'e5a26e6635401f83847d1556f647d0917187c8972c95f9883a386a4272adb410'::TEXT, ARRAY[545]::BIGINT[]),
    (162::BIGINT, 'El profesor es nuevo pero explica bastante bien. Es bastante fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '693390edfebf1779c523a7c9a2b55912290f1969f23c75d631a5918107a53a98'::TEXT, ARRAY[545]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
